mapper.select:
SELECT a.AUXILIARY_ID as auxiliaryId, a.AUXILIARY_CODE as auxiliaryCode, a.AUXILIARY_NAME as auxiliaryName, a.AUXILIARY_TYPE as auxiliaryType, a.PARENT_ID as parentId, p.AUXILIARY_NAME as parentName, CASE WHEN a.PARENT_ID IS NULL THEN 1 ELSE 2 END as auxiliaryLevel, a.IS_LEAF as isLeaf, a.IS_ENABLED as isEnabled, a.SORT_ORDER as sortOrder, a.BOOK_ID as bookId, a.TENANT_ID as tenantId, a.VERSION as version, a.CREATE_TIME as createTime, a.UPDATE_TIME as updateTime, a.CREATOR as creator, a.UPDATER as updater FROM T_AUXILIARY_ITEM a LEFT JOIN T_AUXILIARY_ITEM p ON a.PARENT_ID = p.AUXILIARY_ID AND p.IS_DELETED = 0 WHERE a.IS_DELETED = 0
AND a.BOOK_ID = #{param.bookId}
AND a.TENANT_ID = #{param.tenantId}
AND a.AUXILIARY_CODE LIKE '%' || #{param.auxiliaryCode} || '%'
AND a.AUXILIARY_NAME LIKE '%' || #{param.auxiliaryName} || '%'
AND a.AUXILIARY_TYPE = #{param.auxiliaryType}
AND a.PARENT_ID = #{param.parentId}
AND a.IS_LEAF = #{param.isLeaf}
AND a.IS_ENABLED = #{param.isEnabled}
ORDER BY a.AUXILIARY_TYPE ASC, a.SORT_ORDER ASC, a.AUXILIARY_CODE ASC

SELECT * FROM T_AUXILIARY_ITEM 
WHERE IS_DELETED = 0 
AND AUXILIARY_CODE = #{auxiliaryCode}
AND AUXILIARY_TYPE = #{auxiliaryType}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

    AND AUXILIARY_ID != #{excludeId}

AND ROWNUM = 1

SELECT AUXILIARY_ID as auxiliaryId, AUXILIARY_CODE as auxiliaryCode, AUXILIARY_NAME as auxiliaryName, AUXILIARY_TYPE as auxiliaryType, PARENT_ID as parentId, IS_LEAF as isLeaf, IS_ENABLED as isEnabled, SORT_ORDER as sortOrder, BOOK_ID as bookId, TENANT_ID as tenantId, VERSION as version, CREATE_TIME as createTime, UPDATE_TIME as updateTime, CREATOR as creator, UPDATER as updater FROM T_AUXILIARY_ITEM WHERE IS_DELETED = 0 AND BOOK_ID = #{bookId} AND TENANT_ID = #{tenantId}
AND PARENT_ID = #{parentId}
AND PARENT_ID IS NULL
ORDER BY SORT_ORDER ASC, AUXILIARY_CODE ASC

SELECT AUXILIARY_ID as auxiliaryId, AUXILIARY_CODE as auxiliaryCode, AUXILIARY_NAME as auxiliaryName, AUXILIARY_TYPE as auxiliaryType, PARENT_ID as parentId, IS_LEAF as isLeaf, IS_ENABLED as isEnabled, SORT_ORDER as sortOrder, BOOK_ID as bookId, TENANT_ID as tenantId, VERSION as version, CREATE_TIME as createTime, UPDATE_TIME as updateTime, CREATOR as creator, UPDATER as updater FROM T_AUXILIARY_ITEM WHERE IS_DELETED = 0 AND BOOK_ID = #{bookId} AND TENANT_ID = #{tenantId} AND IS_ENABLED = 1
AND AUXILIARY_TYPE = #{auxiliaryType}
ORDER BY AUXILIARY_TYPE ASC, SORT_ORDER ASC, AUXILIARY_CODE ASC

